export function RoomPanel(
{ room }: { room: any }) {
  return (
    <div className="roomPanel">
      <h3>{room.name}</h3>
      <ul>
        {room.reservations.map((reservation) => {
          return (
            <li key={reservation.id}>
              {reservation.room.name} - {reservation.room.capacity}
            </li>
          );
        })}
      </ul>
    </div>
  );
}
